{
  "items": [
    {
      "name": "MvPolynomial.linearIndependent_X",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ (σ : Type u) (R : Type v) [inst : CommSemiring R], LinearIndependent R MvPolynomial.X"
    },
    {
      "name": "MvPolynomial.sum_homogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R] (φ : MvPolynomial σ R),\n  ∑ i ∈ Finset.range (φ.totalDegree + 1), (MvPolynomial.homogeneousComponent i) φ = φ"
    },
    {
      "name": "MvPolynomial.as_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R),\n  p = ∑ v ∈ p.support, (MvPolynomial.monomial v) (MvPolynomial.coeff v p)"
    },
    {
      "name": "MvPolynomial.universalFactorizationMapPresentation",
      "module_name": "Mathlib.RingTheory.Polynomial.UniversalFactorizationRing",
      "kind": "definition",
      "type": "(R : Type u_1) →\n  [inst : CommRing R] →\n    (n m k : ℕ) →\n      (hn : n = m + k) →\n        Algebra.PreSubmersivePresentation (MvPolynomial (Fin n) R)\n          (TensorProduct R (MvPolynomial (Fin m) R) (MvPolynomial (Fin k) R)) (Fin m ⊕ Fin k) (Fin n)"
    },
    {
      "name": "MvPolynomial.support_sum_monomial_coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R),\n  ∑ v ∈ p.support, (MvPolynomial.monomial v) (MvPolynomial.coeff v p) = p"
    }
  ]
}
